window.DOSIK=window.DOSIK||{};DOSIK["sa_mgmt"]={"#1":[{"t":"vs","title":"상황요인과 구조변수","cols":[{"name":"상황요인","items":["조직구조 설계의 상황요인: 규모, 기술, 환경, 전략","네 가지 전부 해당","표준화(공식화)는 상황요인이 아님"]},{"name":"구조변수","items":["구조변수(설계변수): 복잡성(분화: 수평·수직·공간), 공식화, 집권화","표준화(공식화)는 구조변수"]},{"name":"상황적합이론","items":["조직 효과성은 상황요인과 구조의 적합도에 달림"]}]},{"t":"vs","title":"기계적 구조와 유기적 구조","cols":[{"name":"기계적 구조","items":["부서 구분 엄격","의사결정 집중화(집권화)","전문화·공식화 수준 높음","통제범위 좁음","안정적 환경에 적합"]},{"name":"유기적 구조","items":["분권화","낮은 공식화","넓은 통제범위","팀·수평 의사소통 중심","불확실하고 변화가 큰 환경에 적합","통제범위가 더 넓은 쪽은 유기적 구조 · 기계적 구조에 넣으면 오답"]}]},{"t":"table","title":"기술 유형별 분류","head":["학자","분류"],"rows":[["우드워드","소량단위 생산기술, 대량생산기술, 연속공정생산기술"],["페로우","일상적 기술, 비일상적 기술, 장인기술, 공학적 기술 · 두 축: 과업 다양성(예외 빈도), 문제 분석 가능성"],["톰슨","중개형 기술, 연속형 기술, 집약형 기술 · 상호의존성: 집합적(pooled), 순차적(sequential), 교호적(reciprocal)"],["2024 기출 정답","ㄱ 대량생산기술, ㄴ 장인기술, ㄷ 중개형 기술"]]},{"t":"tree","title":"조직구조 유형과 구성부문","root":"조직구조","branches":[["매트릭스조직","기능별 부문화와 제품별 부문화를 결합 · 명령일원화 원칙이 깨져 이중 보고 · 가상조직, 네트워크조직, 하이퍼텍스트조직, 애드호크라시는 매트릭스가 아닌 다른 유형(2023 기출 오답 보기)"],["기능별·사업부제 조직","기능별 조직은 같은 기능끼리 묶음 · 사업부제 조직은 제품·지역·고객별로 묶음"],["애드호크라시","임시 팀 중심의 유연한 조직 · 높은 수평 분화와 낮은 공식화"],["민쯔버그 구성부문","5가지 구성부문: 핵심운영 부문, 전략 부문(전략상층부), 중간관리 부문(중간라인), 기술전문가 부문(기술구조), 지원스탭 부문 · 매트릭스 부문은 구성부문이 아님"],["민쯔버그 조정 메커니즘","5가지: 상호조절, 직접감독, 작업과정 표준화, 작업결과(산출) 표준화, 기술(숙련) 표준화"],["민쯔버그 구조 유형","5가지: 단순구조, 기계적 관료제, 전문적 관료제, 사업부제 구조, 애드호크라시"]]}],"#2":[{"t":"tree","title":"권력의 원천","root":"권력 원천","branches":[["공식적 권력","역할과 지위에 따른 계층구조에서 나오고 그 지위를 떠나면 유지되기 어렵다 · 합법적 권력, 보상적 권력, 강압적 권력"],["개인적 권력","전문적 권력, 준거적 권력 · 능력과 인격을 인정받아 생김"],["정보적 권력","개인적 권력의 하위가 아님 · 기출은 개인적 권력에 전문적·정보적을 넣은 선지를 오답으로 처리"],["원래 5가지","합법적, 보상적, 강압적, 준거적, 전문적 · 레이븐이 정보적 권력을 추가"]]},{"t":"table","title":"피들러의 상황적합이론","head":["항목","내용"],"rows":[["LPC","least preferred coworker: 함께 일하기 가장 싫었던 동료를 평가하는 척도 · 점수가 높으면 관계지향적 리더, 낮으면 과업지향적 리더"],["상황요인 3가지","리더-부하 관계, 과업구조, 리더의 직위권력 · 3요인 이분법으로 8개 상황"],["리더에게 매우 호의적인 상황","과업지향적 리더십이 효과적"],["리더에게 매우 비호의적인 상황","과업지향적 리더십이 효과적"],["중간 정도로 호의적인 상황","관계지향적 리더십이 효과적"],["비교","효과적인 리더십 스타일은 상황에 따라 다름 · 상황적합이론과 경로-목표이론은 모두 상황을 고려"]]},{"t":"tree","title":"하우스의 경로-목표이론","root":"경로-목표이론","branches":[["리더십 유형 4가지","지시적, 지원적, 참여적, 성취지향적"],["거래적 리더십","경로-목표이론의 유형이 아님(번스·배스의 거래적/변혁적 구분)"],["상황변수","부하 특성(통제위치, 능력, 욕구)과 · 환경 특성(과업구조, 공식 권한체계, 작업집단)"],["이론 틀","리더가 부하의 목표 달성 경로를 명확히 해 동기를 높임 · 기대이론에 바탕"]]},{"t":"table","title":"그 밖의 리더십 이론","head":["이론","내용"],"rows":[["오하이오 주립대","구조주도(과업)와 배려(관계) 두 차원"],["미시간대","직무중심 리더와 종업원중심 리더"],["블레이크와 머튼 관리격자","생산에 대한 관심 x 인간에 대한 관심, 9x9"],["허시와 블랜차드 상황적 리더십","부하 성숙도에 따라 지시형, 설득형, 참여형, 위임형"],["변혁적 리더십(배스)","이상적 영향력(카리스마), 영감적 동기부여, 지적 자극, 개별적 배려"],["거래적 리더십","보상과 교환으로 성과 유도(조건적 보상, 예외관리)"]]}],"#3":[{"t":"table","title":"내용이론(욕구기반 이론)","head":["이론","내용"],"rows":[["매슬로","생리, 안전, 소속(사회), 존경, 자아실현 · 하위 욕구 충족 후 상위 욕구 발현"],["앨더퍼 ERG","존재(Existence), 관계(Relatedness), 성장(Growth) · 욕구기반 이론에 속함 · 여러 욕구 동시 작용 가능, 상위 욕구 좌절 시 하위 욕구로 퇴행(좌절-퇴행)"],["허즈버그 2요인","위생요인(임금, 감독, 작업조건, 회사 정책, 대인관계)은 불만을 줄이고, 동기요인(성취, 인정, 일 자체, 책임, 승진, 성장)이 만족을 높임 · 동기가 직무 자체의 본질에서 나온다고 봄 · 외부 보상·직무 조건에서 나온다고 하면 오답"],["맥클랜드 성취동기이론","성취욕구, 권력욕구, 친교욕구"]]},{"t":"tree","title":"과정이론","root":"과정이론","branches":[["브룸 기대감","노력이 수행으로 이어질 믿음 · 노력이 수행을 이끌어 낼 것이라는 믿음은 기대감, 도구성이라고 하면 오답"],["브룸 수단성","도구성: 수행이 보상으로 이어질 믿음"],["브룸 유의성","보상의 매력"],["브룸 동기부여 힘","동기부여 힘 = 기대감 x 수단성 x 유의성 · 사전 기대와 사후 성과의 차이로 동기를 설명하지 않음"],["아담스 공정성(형평)이론","자신의 산출/투입 비율을 타인의 산출/투입 비율과 비교 · 비율이 일치하지 않는다고 느끼면 불형평을 줄이려는 동기가 발생"],["로크 목표설정이론","명확하고 구체적이며 도전적인 목표가 수행동기를 높여 과업수행 향상 · 보조 조건: 목표 수용, 피드백, 자기효능감"]]},{"t":"vs","title":"공정성이론의 투입과 산출","cols":[{"name":"투입","items":["시간, 노력, 경험, 창의성, 교육 등","임금은 투입이 아님"]},{"name":"산출(결과)","items":["임금, 승진, 인정, 복리후생 등","임금은 산출(결과)"]}]},{"t":"tree","title":"자기결정이론과 직무특성이론","root":"자기결정이론과 직무특성이론","branches":[["자기결정이론(리안과 디시)","내적동기에 영향을 미치는 기본욕구 3가지는 자율성, 유능성, 관계성 · 통제성, 소속성은 기본욕구가 아님 · 내적 동기와 외적 동기의 특징과 관계를 체계적으로 다룸 · 기출 2024-62는 정답표에 3(로크)로 기록돼 있으나 내용상 해당 이론은 5(자기결정이론)"],["동기 이론의 분류","욕구기반 이론(매슬로, ERG, 맥클랜드, 허즈버그), 인지과정 이론(기대, 공정성, 목표설정), 직무기반 이론(직무특성모형), 행동적 이론(강화)"],["직무특성모형 핵심 직무차원","해크만과 올드햄의 핵심 직무차원 5가지: 기술 다양성, 과업 정체성, 과업 중요성, 자율성, 피드백 · 중요 심리상태 3가지: 일의 의미감, 일의 결과에 대한 책임감, 일의 결과에 대한 지식"],["일의 의미감","기술 다양성, 과업 정체성, 과업 중요성"],["경험된 책임감과 결과 지식","경험된 책임감을 만드는 직무특성은 자율성 · 결과에 대한 지식을 만드는 직무특성은 피드백"],["동기부여잠재점수","성장욕구 강도가 직무특성과 결과 사이를 조절 · 동기부여잠재점수 = [(기술 다양성 + 과업 정체성 + 과업 중요성)/3] x 자율성 x 피드백 · 작업설계이론: 직무를 적절히 설계하면 작업 자체가 개인의 동기를 높인다"]]}],"#4":[{"t":"flow","title":"터크만의 팀 발달","steps":["형성기(forming)","격동기(storming, 갈등)","규범기(norming)","수행기(performing)","해산기(adjourning)"]},{"t":"table","title":"터크만 팀 발달 5단계","head":["항목","내용"],"rows":[["규범기","개별적 사람의 집합이 의미 있는 팀이 되는 단계는 규범기"],["단계의 반복","시간이 지나며 단계를 왔다 갔다 반복하며 발달한다고 가정"],["팀 모형 비교","맥그래스(투입-과정-산출 IPO 모형), 해크만(팀 효과성 조건), 캠피온(팀 설계), 그래드스테인(조직 맥락 모형) · 5단계 모형은 터크만"]]},{"t":"table","title":"집단의사결정 기법","head":["기법","내용"],"rows":[["브레인스토밍","다른 참여자 아이디어에 대한 비판 금지"],["명목집단법","참여자 간 토론을 하지 않고 개별 아이디어를 낸 뒤 취합·투표"],["델파이법","전문가에게 익명 설문을 반복 · 시간이 오래 걸려 긴박한 문제에는 부적합"],["프리모텀","프로젝트가 실패했다고 미리 가정하고 실패 원인을 찾음"],["지명반론자법(악마의 옹호자)","집단사고의 위험을 줄임"]]},{"t":"tree","title":"집단사고와 응집성","root":"집단사고와 응집성","branches":[["집단사고(제니스) 선행조건","집단의 고립, 외부 위협(스트레스), 지시적 리더, 높은 응집성, 대안 탐색 절차 부재"],["기출 2025-65 정답","집단이 외부로부터 고립되어 있을 때, 외부로부터 위협이 있을 때 · 리더가 민주적일 때와 응집력이 낮을 때는 해당하지 않음"],["2024 기출","구성원 간 낮은 응집성과 친밀성을 집단사고의 선행요인으로 서술한 문장을 옳은 것으로 처리(2025 기출 및 일반 교과와 상충)"],["증상 예","불가침 환상, 집단 합리화, 외부집단 상투화, 동조 압력, 자기검열, 만장일치 환상"],["집단 응집성","높으면 집단 규범 방향에 따라 성과가 높아지거나 낮아질 수 있음"]]},{"t":"table","title":"사회적 태만·촉진·억제와 집단 유형","head":["항목","내용"],"rows":[["사회적 태만","집단에서 개인 노력이 줄어드는 현상 · 남만큼만 하기 효과(sucker effect)는 사회적 태만의 한 현상"],["사회적 억제","다른 사람의 존재가 개인 성과에 부정적 영향을 미침"],["사회적 촉진","타인의 존재가 쉬운(숙련된) 과제 수행을 높이고 어려운 과제 수행은 낮춤(자이언스)"],["관중 효과와 공행동 효과","관중 효과(audience effect)는 관찰하는 사람이 있을 때 나타남 · 같은 일을 함께 수행할 때 나타나는 것은 공행동 효과(coaction effect)"],["교차기능팀","조직 내 여러 부서 구성원으로 이루어진 팀"],["지휘집단(command group)","같은 상사에게 업무보고를 하는 부하직원 집단 · 공식적 집단"],["집단 효능감","구성원이 공동의 목표를 성공적으로 달성할 능력이 있다고 믿는 것"],["규범 준수","집단 내 행동의 예측력을 높이고 응집력을 높임"],["공식적·비공식적 집단","공식적 집단: 지휘집단, 임무집단 · 비공식적 집단: 이익집단, 우호집단"]]}],"#5":[{"t":"table","title":"직업 스트레스 모델","head":["모델","내용"],"rows":[["요구-통제 모델(카라섹)","업무 요구가 높고 업무 통제력이 낮을 때 스트레스가 가장 높음"],["직무요구-자원 모델(JD-R)","업무량 외에도 다양한 요구가 있음을 인식하고, 그 요구가 종업원의 안녕과 동기에 미치는 영향을 종단 설계로 연구"],["노력-보상 불균형 모델","보상이 노력에 비례하지 않을 때 스트레스가 큼"],["자원보존 이론(COR)","자원의 실제 손실 또는 손실 위협이 스트레스를 일으킴 · 종업원은 시간에 걸쳐 자원을 축적하려는 동기가 있음"],["사람-환경 적합 모델","개인과 환경 간 적합도가 낮은 업무 환경을 스트레스원으로 지각"],["셀리에의 일반적 적응증후군","경고(alarm), 저항(resistance), 소진(exhaustion) 3단계"],["비르와 프랜즈","직업 스트레스를 의학적 접근, 임상·상담적 접근, 공학심리학적 접근, 조직심리학적 접근 네 관점으로 설명"],["비어와 뉴먼 모델","요소(facet): 개인 요소, 환경 요소, 과정 요소, 시간 요소 · 경제 요소는 아님"]]},{"t":"tree","title":"역할 스트레스원과 감소 방법","root":"직업 스트레스","branches":[["역할 모호성","종업원이 자신의 직무 기능과 책임이 무엇인지 불명확하게 느끼는 정도"],["그 밖의 역할 스트레스원","역할 갈등, 역할 과부하"],["스트레스원 감소 방법","조직 스트레스원 자체를 줄이는 방법: 자율성을 높인 직무 설계, 의사결정 참여 기회 확대, 관리자의 의사소통 훈련, 종업원의 갈등해결기법 훈련"]]},{"t":"tree","title":"KOSS","root":"KOSS(한국인 직무스트레스 요인 평가도구)","branches":[["하위 요인","물리환경, 직무요구, 직무자율성 결여, 관계갈등, 직무불안정, 조직체계, 보상부적절, 직장문화"],["직무 요구 문항","일이 많아 항상 시간에 쫓긴다"],["조직 체계 문항","업무 수행 과정에 내 생각을 반영할 기회와 통로가 있다"],["직무자율성 영역","작업시간·업무 수행 과정에서 스스로 결정할 권한이 있다는 문항은 직무 불안정이 아니라 직무자율성 영역"]]},{"t":"table","title":"조직 태도와 반생산적 업무행동","head":["항목","내용"],"rows":[["직무기술지표(JDI)","하위 요인: 업무 자체, 보수, 승진 기회, 감독, 동료 · 작업 조건은 하위 요인이 아님"],["조직몰입(앨런과 마이어)","정서적 몰입, 지속적 몰입(이직 비용), 규범적 몰입(의무감, 죄책감) · 개인적 의미 부여, 그만두면 큰 비용, 그만두면 죄책감 문항은 조직몰입을 측정"],["조직정의","분배 정의, 절차 정의, 상호작용 정의"],["조직지지 지각(POS)","조직이 자신의 기여를 인정하고 복지를 배려한다는 믿음"],["반생산적 업무행동(CWB)","직장 내 조직과 구성원에게 해로운 의도적 행동 · 개인적 범주와 조직적 범주로 분류 · 일탈행동(Deviance)은 CWB에 속하며 조직에 해로운 행동"],["CWB 유형(스펙터)","철회, 사보타주, 생산일탈, 타인학대, 절도 · 사보타주: 조직의 장비·재산 손상, 재료·공급물품 의도적 낭비, 자기 업무영역 더럽히기 등 업무 방해 의도의 시도"],["직장무례(workplace incivility)","낮은 강도의 무례한 행동"],["OCB","생산적 행동, 친사회적 행동, 역할 외 행동"]]}],"#6":[{"t":"tree","title":"직무분석","root":"직무분석","branches":[["목적","직무분석은 인력확보와 인력개발에 필요하고 교육훈련 내용과 안전사고 예방 정보를 제공"],["직무기술서","직무의 내용(과업, 책임)"],["직무명세서","직무수행자가 갖춰야 할 자격요건인 인적 특성"],["직무분석가","직무 간 관계에 관한 정확한 정보를 주는 정보 제공자"],["정보수집 방법","관찰법, 면접법, 질문지(설문)법, 작업일지법, 중요사건법 · 설문조사는 효율적이고 비용이 적게 듦"]]},{"t":"vs","title":"과업 중심과 작업자 중심 접근","cols":[{"name":"과업 중심","items":["과업질문지(TI), 기능적 직무분석(FJA) 등","직위분석질문지(PAQ)를 과업 중심의 대표 예라고 하면 오답"]},{"name":"작업자 중심","items":["직무 성공에 필요한 인적 속성(지식, 기술, 능력, 기타 특성: KSAO)을 조사","직위분석질문지(PAQ)는 작업자 중심 방법","PAQ의 주요 차원: 정보 입력, 정신 과정, 작업 결과, 타인과의 관계, 직무 맥락, 기타 직무특성","신체 과정(body processes)은 PAQ 차원이 아님","그 밖의 방법: 직무요소질문지(JCI), 직무분석 시스템(JAS)"]}]},{"t":"vs","title":"직무평가와 인사평가","cols":[{"name":"직무평가","items":["대상은 직무 자체이며 다른 직무와의 상대적 가치를 평가 · 중요성, 난이도, 위험도 등을 반영","조직 목표 달성에 더 공헌하는 직무가 더 가치 있다고 봄"]},{"name":"인사평가","items":["직무수행자(종업원)를 평가하거나 기업목표 공헌도를 보는 것은 직무평가가 아니라 인사평가"]}]},{"t":"table","title":"직무평가 4방법","head":["방법","내용"],"rows":[["서열법","비계량 방법"],["분류법","비계량 방법"],["점수법","계량 방법 · 직무의 평가요소별로 점수를 매겨 합산"],["요소비교법","계량 방법 · 기준직무와 요소별로 비교해 화폐가치(임률)로 환산"]]}],"#7":[{"t":"table","title":"타당도의 종류","head":["종류","내용"],"rows":[["동시 타당도","현직 종업원에게 검사를 실시해 현재 생산성 자료와의 상관을 구함"],["예측 타당도","지원자에게 검사를 실시하고 채용 후 일정 기간 뒤 성과와의 상관을 구함"],["준거관련 타당도","동시 타당도와 예측 타당도를 포함"],["내용 타당도","검사 문항이 측정 영역을 대표하는 정도 · 안면 타당도(피검자가 보기에 그럴듯한 정도)와 다른 개념"],["내적 타당도(실험 설계)","종속변인의 변화가 독립변인 때문이라고 신뢰하는 정도 · 가외변인 통제가 핵심 · 실험실 실험이 준실험보다 통제를 더 많이 함"]]},{"t":"table","title":"신뢰도의 종류","head":["종류","내용"],"rows":[["검사-재검사 신뢰도","같은 검사를 시간 간격을 두고 두 번 실시한 점수의 상관"],["동형검사(대안형) 신뢰도","역균형화(counterbalancing)로 순서효과를 상쇄 · 검사-재검사에는 사용하지 않음"],["내적일치 신뢰도","문항들을 각각 작은 검사로 보고 문항 간 상관으로 확인(쿠더-리처드슨 공식 20, 크론바흐 알파)"],["평가자 간 신뢰도","여러 평가자 점수의 일치도"]]},{"t":"tree","title":"선발 도구의 유용성","root":"선발 도구의 유용성","branches":[["타당도","예측변인의 타당도가 클수록 합격 집단의 평균 준거수행이 전체 집단보다 더 높아짐"],["선발률","선발률(선발인원/지원자수)이 낮을수록 예측변인의 가치가 커짐"],["기초율","기존 방식으로 선발해도 성공할 비율이 높으면 새 선발도구의 유용성은 낮아짐"],["선발률과 기초율","상관은 0(서로 독립)"],["산점도","예측변인과 준거수행의 산점도: 1사분면(높음-높음)과 3사분면(낮음-낮음)이 채워진 타원형이 정적 상관"]]},{"t":"table","title":"인력 예측·인사평가 방법과 평가 오류","head":["항목","내용"],"rows":[["인력 수요예측 기법","회귀분석, 델파이법"],["인력 공급예측 기법","기능목록 분석, 대체도 분석"],["상대평가법","서열법, 쌍대비교법, 강제할당법"],["절대평가법","평정척도법, 행위기준척도법(BARS), 체크리스트법 등 · BARS는 직무 행동 사례를 척도 기준(anchor)으로 삼아 평가 · 재무적 성과 크기를 평가하는 방법이 아님"],["BSC 평가법","재무적 성과와 비재무적 성과를 모두 평가"],["MBO 평가법","상사와 합의한 목표 대비 성과를 측정"],["서열법","피평가자 간 순위를 부여"],["다면평가법","상사, 동료, 부하 등 다양한 사람이 평가에 참여"],["후광효과","피평정자의 총체적 인상으로 평가"],["관대화·엄격화 경향","관대화 경향: 실제보다 높게 평가 · 엄격화 경향: 실제보다 의도적으로 낮게 평가"],["중앙집중 경향","극단적으로 높거나 낮은 평정을 피하고 평균치에 가깝게 평정"],["초두효과(primacy effect)","처음에 나타난 정보에 영향을 받음 · 마지막 정보를 토대로 하면 최근효과"],["그 밖의 오류","유사효과, 대비효과, 상동적 태도, 논리적 오류"]]}],"#8":[{"t":"table","title":"숍제도와 단체교섭 유형","head":["항목","내용"],"rows":[["클로즈드 숍(기본 형태)","노조 조합원만 채용 가능"],["유니온 숍(기본 형태)","조합원이 아니라도 채용될 수 있으나 채용 후 일정 기간 내에 노조에 가입해야 함"],["오픈 숍(기본 형태)","노조 가입 여부와 무관하게 채용·고용 유지"],["에이전시 숍(변형 형태)","비조합원도 단체교섭 혜택을 받으므로 조합비에 해당하는 금액을 납부"],["프레퍼렌셜 숍(변형 형태)","채용 시 조합원을 우선 채용"],["메인티넌스 숍(변형 형태)","가입한 조합원은 협약 기간 동안 조합원 자격 유지"],["협상","둘 이상 당사자가 희소한 자원의 분배를 결정하는 과정"],["분배적 교섭","전체 자원(pie)이 고정, 내가 이익이면 상대는 손해(제로섬)"],["통합적 교섭","윈-윈 해결책이 있다는 전제"],["기업별 교섭","특정 기업·사업장 단위 노조가 해당 기업 사용자 대표와 교섭"],["통일교섭·대각선 교섭","통일교섭: 산업별 노조와 사용자단체 · 대각선 교섭: 산업별 노조와 개별 기업 사용자"],["공동교섭·집단교섭","공동교섭: 상급단체와 단위노조가 공동으로 참여 · 집단교섭: 여러 노조와 여러 사용자가 공동 교섭"]]},{"t":"table","title":"부당노동행위(노동조합법 제81조)","head":["조항","내용"],"rows":[["제81조 제1항","사용자는 제81조제1항 각 호의 행위를 할 수 없다"],["제1호","노조 가입·조직·정당한 조합 업무를 이유로 한 해고나 불이익을 주는 행위"],["제2호","근로자가 어느 노조에 가입하지 않을 것 또는 탈퇴할 것을 고용조건으로 하거나, 특정 노조 조합원이 될 것을 고용조건으로 하는 행위(황견계약) · 2023 기출: 가입·탈퇴를 고용조건으로 하는 행위는 황견계약"],["제2호 단서","노조가 해당 사업장 근로자의 3분의 2 이상을 대표할 때는 조합원 될 것을 고용조건으로 하는 단체협약 체결이 예외 · 이 경우에도 제명·탈퇴 후 새 노조 조직·다른 노조 가입을 이유로 신분상 불이익을 줄 수 없음"],["제3호","노조 대표자 또는 위임받은 자와의 단체협약 체결 기타 단체교섭을 정당한 이유 없이 거부하거나 해태"],["제4호","노조 조직·운영에 대한 지배·개입, 근로시간 면제한도를 초과한 급여 지급, 노조 운영비 원조"],["제4호 예외","근로시간 중 제24조제2항 활동 허용, 후생자금·경제상 불행 구제 기금 기부, 최소한 규모의 노조사무소 제공, 자주적 운영·활동을 침해할 위험이 없는 범위의 운영비 원조"],["제5호","정당한 단체행위 참가, 부당노동행위 신고·증언·증거 제출을 이유로 한 해고나 불이익"],["운영비 원조의 침해 위험 판단","고려 사항: 목적과 경위, 횟수와 기간, 금액과 방법, 노조 총수입 대비 비율, 관리방법과 사용처"]]},{"t":"tree","title":"노동쟁의와 쟁의행위","root":"노동쟁의","branches":[["노동쟁의","노동조합과 사용자 또는 사용자단체 간 근로조건 결정 등에 관한 주장의 불일치로 발생한 분쟁상태 · 주장의 불일치는 자주적 교섭으로 합의할 여지가 없는 경우"],["쟁의행위","파업, 태업, 직장폐쇄 기타 주장을 관철할 목적으로 행하는 행위와 이에 대항하는 행위로서 업무의 정상적 운영을 저해하는 행위"],["노조 측 수단","파업, 준법투쟁, 불매운동, 생산통제 등 · 대체고용은 사용자 측의 대항 행위로 성격이 다름"],["통보","노동관계 당사자는 노동쟁의가 발생하면 어느 일방이 상대방에게 서면으로 통보"],["조정 전치","쟁의행위는 조정절차를 거치지 않으면 할 수 없음 · 조정기간 내 조정이 종료되지 않거나 중재재정기간 내 중재재정이 없으면 예외"]]},{"t":"table","title":"조정·중재·긴급조정","head":["항목","내용"],"rows":[["담당","노동쟁의 조정은 노동위원회가 담당 · 조정, 중재, 긴급조정 등"],["조정 개시","노동위원회는 일방이 조정을 신청하면 지체 없이 조정을 개시"],["조정기간","신청일부터 일반사업 10일, 공익사업 15일 이내 · 당사자 합의로 일반사업 10일, 공익사업 15일 이내 연장 가능"],["조정안","조정위원회(단독조정인)는 조정안을 작성해 제시하고 수락을 권고하며 이유를 붙여 공표할 수 있음 · 수락 거부로 조정 여지가 없다고 판단되면 조정 종료를 결정하고 양 당사자에게 통보"],["해석·이행방법 견해","조정안 해석·이행방법 견해는 요청받은 날부터 7일 이내 제시 · 견해 제시 전까지 해석·이행에 관해 쟁의행위 불가"],["효력","조정서의 내용은 단체협약과 동일한 효력 · 제시된 해석·이행방법 견해는 중재재정과 동일한 효력"],["임의조정","임의조정(사적 조정·중재): 당사자 쌍방 합의 또는 단체협약이 정하는 바에 따라 다른 조정·중재 방법으로 해결 가능 · 노동위원회에 신고 · 결과는 단체협약과 동일한 효력"],["중재 개시 요건","양 당사자가 함께 중재 신청, 또는 일방이 단체협약에 따라 중재 신청 · 노동쟁의가 중재에 회부되면 그 날부터 15일간 쟁의행위 불가"],["중재재정","중재재정의 내용은 단체협약과 동일한 효력 · 재심 신청·행정소송이 효력을 정지시키지 않음 · 중재재정이 위법·월권이면 지방노동위원회 재정서 송달일부터 10일 이내 중앙노동위원회에 재심 신청 · 중앙노동위원회 재정·재심결정은 송달일부터 15일 이내 행정소송 제기 · 기간 내 불복하지 않으면 확정"],["긴급조정","고용노동부장관이 결정 · 쟁의행위가 공익사업 관련이거나 규모가 크거나 성질이 특별해 국민경제를 현저히 해하거나 일상생활을 위태롭게 할 위험이 현존할 때 · 결정 전 중앙노동위원회 위원장 의견 청취 · 결정 시 지체 없이 이유를 붙여 공표하고 중앙노동위원회와 당사자에게 통고"],["긴급조정 공표 뒤","공표 시 즉시 쟁의행위 중지, 공표일부터 30일 경과 전 재개 불가 · 중앙노동위원회는 통고를 받으면 지체 없이 조정을 개시 · 위원장은 조정 가망이 없으면 공익위원 의견을 들어 중재 회부 여부를 통고받은 날부터 15일 이내에 결정"],["공익사업","정기노선 여객운수·항공운수, 수도·전기·가스·석유정제·석유공급, 공중위생·의료·혈액공급, 은행·조폐, 방송·통신"],["필수공익사업","철도·도시철도·항공운수, 수도·전기·가스·석유정제·석유공급, 병원·혈액공급, 한국은행, 통신"]]}],"#9":[{"t":"table","title":"재고비용과 EOQ","head":["항목","내용"],"rows":[["재고 관련 비용","재고유지비용, 주문(생산준비)비용, 재고부족(품절)비용 · 재고비용은 유지비용과 부족비용만의 합이 아님"],["재고유지비용","보관설비 비용, 진부화 비용, 보험 비용 등 · 생산준비 비용은 주문비용 쪽, 품절 비용은 재고부족비용 쪽"],["재고 비축","재고를 많이 비축할수록 좋은 것이 아님 · 유지비용과 진부화 위험이 커짐"],["EOQ 가정","수요 일정, 조달기간 알려짐, 재고부족 불허, 재고유지비용은 평균재고에 비례, 제품 구입단가는 발주량과 무관(수량할인 없음) · 구입단가가 발주량과 반비례한다는 서술은 EOQ 가정이 아님"],["평균재고","1회 주문량 Q일 때 평균재고는 Q/2"],["비용과 주문량","재고유지비용은 주문량 Q에 비례(Q/2 x H), 주문비용은 주문량에 반비례(D/Q x S)"],["총재고비용선","U자 모양 · 최저점(EOQ)에서 유지비용과 주문비용이 같음"],["공식","EOQ = 루트(2DS/H) · D 연간 수요, S 1회 주문비용, H 단위당 연간 유지비용"],["풀이 순서","D, S, H 확인 -> 2DS/H 계산 -> 제곱근 · 총비용 = 구입비 + (D/Q)S + (Q/2)H"],["재주문점","재주문점 = 일평균 수요 x 조달기간 (+ 안전재고)"]]},{"t":"table","title":"수요예측","head":["항목","내용"],"rows":[["지수평활법","Ft = Ft-1 + a(At-1 - Ft-1) · 최근 자료에 더 큰 비중 · a가 클수록 최근 실적 반영 큼"],["지수평활 예","Ft-1 = 1,000, a = 0.05, At-1 = 1,200 이면 Ft = 1,000 + 0.05 x 200 = 1,010"],["정성적(주관적) 방법","델파이법, 시장조사법, 자료유추법, 판매원 의견종합법, 경영자 판단 등 · 이동평균법은 정량적 시계열 기법이므로 정성적 방법이 아님 · 자료유추법은 유사제품의 수요를 참고하는 정성적 기법 · 델파이법은 전문가의 식견과 경험에 기초하는 정성적 기법"],["시계열분석법","과거 수요 패턴이 미래에도 지속된다는 가정의 정량적 기법 · 변동요소는 추세, 주기(순환), 계절성, 불규칙성"],["인과형 예측법","수요에 영향을 주는 원인변수를 분석해 예측하는 정량적 기법(회귀분석 등)"],["우연(불규칙) 변동","예측·통제가 어려운 변동"],["추세","수요가 장기적으로 증가·감소하는 경향"],["평균수준","과거 수요의 평균"],["계절변동","1년 중 계절에 따라 증가·감소(여름 아이스크림, 겨울 스키 장비)"],["순환변동(cycles)","1년보다 긴 주기로 반복(경기변동 등) · 단기간 급변 반복이 아님"]]},{"t":"table","title":"총괄생산계획·MRP·JIT·공급사슬","head":["항목","내용"],"rows":[["휴리스틱 총괄생산계획 기법","매개변수에 의한 생산계획, 생산전환 탐색법, 서어치 디시즌 룰, 경영계수이론 · 선형계획법은 최적화 기법으로 휴리스틱이 아님"],["MRP 입력 자료","자재명세서(BOM), 주생산일정계획(MPS), 재고기록철 · 계획발주량, 예외보고서는 MRP의 출력물"],["MRP","수요예측에 근거한 기본일정에서 종속품목의 양과 시기를 결정 · JIT의 장점이 아님"],["JIT 특징","부품·공정 표준화, 공급자와의 원활한 협력(한정된 수의 공급자와 유대), 다기능 작업자, 칸반시스템, 재고수준 감소, 낭비 제거로 원가 절감 · 채찍효과 발생은 JIT의 특징이 아님"],["채찍효과","수요 변동이 소비자에서 공급자 쪽(상류)으로 갈수록 증폭 · 원인: 수요예측 갱신, 일괄주문, 가격 변동, 배급 게임, 긴 리드타임 · 완화: 정보 공유, VMI, CPFR, 리드타임 단축, 상시저가정책"],["크로스도킹","입고된 상품을 보관하지 않고 곧바로 분류해 출고"],["VMI(공급자 재고관리)","공급자가 구매자 재고 보충 책임을 맡음"],["CPFR","공급자와 구매자가 수요예측, 판매, 재고 보충계획까지 함께 수립"],["지연 차별화","공통부품을 먼저 생산하고 세부사양을 결정짓는 부품은 나중에 생산"]]},{"t":"table","title":"대량고객화·수율관리·과학적 관리법·사회적 책임","head":["항목","내용"],"rows":[["대량고객화","대량생산 효율로 다양한 고객 요구를 맞춤 · 높은 가격으로 다양한 제품을 제공하는 개념이 아님"],["대량고객화 수단","모듈화 설계·생산, 주문조립생산, 주문 접수 시까지 제품·서비스 차별화를 연기(postponement) · 정유·가스처럼 대량고객화를 적용하기 어려운 산업이 있음"],["서비스 수율관리","효과적인 조건: 재고가 소멸성, 사전 예약 판매 가능, 수요 변동 큼, 수요 세분화 가능, 고정비 높고 변동비 낮음 · 변동비가 높고 고정비가 낮은 경우는 수율관리가 효과적이지 않음"],["테일러 과학적 관리법","차별성과급제, 시간연구, 과업의 표준, 고임금 저노무비 · 개방체계, 작업장의 사회적 조건은 테일러 이론과 거리가 있음(인간관계론 쪽)"],["ISO","ISO 26000이 사회적 책임 국제 지침 · ISO 29000은 아님 · ISO 14000(환경경영시스템)은 결과 중심이 아니라 과정(시스템) 중심"],["CSV(포터와 크래머)","경쟁력 강화와 사회적 가치를 함께 창출 · 사회적 책임 우선이 아님"],["지속가능성","미래 세대의 니즈와 상충되지 않게 현 사회의 니즈를 충족시키는 정책과 전략"],["청정생산 방법","친환경 원자재 사용, 청정 프로세스 활용, 친환경 생산 프로세스 관리"]]}],"#10":[{"t":"table","title":"품질 구루와 TQM","head":["인물·개념","내용"],"rows":[["쥬란","품질삼각축(품질 계획, 품질 관리, 품질 개선)"],["데밍","최고경영진의 장기적 관점 품질관리와 종업원 교육훈련 등을 포함한 14가지 품질경영 철학"],["TQM","프로세스 향상을 위한 지속적 개선, 외부 고객만족과 내부 고객만족을 함께 추구 · 고객 입장에서 품질을 정의하고 모든 구성원이 참여해 품질 향상 · 과제 해결 단계는 PDCA(Plan, Do, Check, Act), DICA는 존재하지 않는 조합"],["크로스비","무결점, 품질은 공짜"],["파이겐바움","TQC"],["이시카와","QC서클, 특성요인도"]]},{"t":"venn","title":"6시그마와 린","a":{"name":"6시그마","items":["시그마는 데이터 산포를 나타내는 표준편차 · 평균보다 산포에 초점","통계기법으로 품질혁신을 달성하는 전사적 품질경영 활동 · 제조업 중심으로 개발됐으나 서비스업에도 적용","추진 로드맵 DMAIC: 정의(define), 측정(measure), 분석(analyze), 개선(improve), 통제(control) 5단계","모토로라가 개발(1980년대) · 애플이 개발한 것이 아님","조직: 챔피언, 마스터 블랙벨트, 블랙벨트, 그린벨트","결점(변동) 감소·제거에 집중","모든 형태의 흐름도를 사용","개선활동은 블랙벨트 등 전담(풀타임) 리더가 맡는 것이 특징","분석도구 Fishbone Diagram은 원인결과 분석도(특성요인도, 이시카와 다이어그램) · 파레토 차트는 항목별 빈도를 크기순으로 나열해 핵심 원인을 찾음"]},"b":{"name":"린","items":["낭비 제거·감소에 집중","가치흐름도(VSM)를 주로 사용"]},"both":["임원급 챔피언의 역할이 중요하고 개선 과제를 전략적 관점에서 선정"]},{"t":"table","title":"품질비용과 관리도","head":["항목","내용"],"rows":[["품질비용","품질비용 = 예방비용 + 평가비용 + 실패비용(내부 실패, 외부 실패)"],["예방비용","품질관리 교육 비용, 신제품 설계 검토 비용 등 · 품질보증 비용은 예방비용이 아님"],["내부 실패비용","재작업 비용"],["R-관리도","계량치의 산포(범위)를 관리 · 불량률 관리에 쓰는 것은 p-관리도"],["ABC 분석","재고·품목을 중요도로 구분하는 기법이지 통계적 공정관리 기법이 아님"]]},{"t":"tree","title":"균형성과표(BSC)","root":"BSC","branches":[["4관점","재무 관점, 고객 관점, 내부 프로세스 관점, 학습과 성장 관점"],["공정성 관점","BSC 관점이 아님"],["제안자","카플란과 노턴이 제안 · 재무적 성과와 비재무적 성과를 모두 평가"]]}],"#11":[{"t":"flow","title":"하인리히 도미노 이론","steps":["사회적 환경·유전적 요소","개인적 결함","불안전행동·불안전상태","사고","재해"]},{"t":"flow","title":"버드 신도미노","steps":["관리 부족(통제 결여)","기본원인(기원)","직접원인(징후)","사고(접촉)","상해(손실)"]},{"t":"flow","title":"아담스의 사고 연쇄","steps":["관리구조 결함","전술적 오류(작전적 오류)","불안전행동·상태","사고","상해"]},{"t":"table","title":"사고연쇄 이론 비교","head":["모델","내용"],"rows":[["하인리히 도미노 이론","사고 원인이 연쇄반응을 일으키는 과정을 도미노로 설명 · 직접 원인인 불안전행동·상태를 제거하면 연쇄가 끊겨 재해 예방"],["하인리히 법칙","중상 1 : 경상 29 : 무상해사고 300"],["버드 모델","재해가 관리부족, 기본원인, 직접원인, 사고가 연쇄해 일어난다고 본 것은 버드 모델"],["아담스","직접원인인 불안전행동·상태를 유발하거나 방치한 전술적 오류를 강조"],["리즌 스위스치즈 모델","여러 방어막의 구멍이 겹쳐 사고 발생"],["하돈 매트릭스 모델","인적·장비·환경 요인 x 사고 전·중·후 단계로 분석"]]}],"#12":[{"t":"def","term":"스웨인·거트먼 오류 분류","text":"스웨인과 거트먼의 인간오류 분류","ex":["생략오류(omission): 해야 할 업무를 수행하지 않음 · 부분으로는 옳으나 전체로는 틀린 것을 옳다고 주장하는 오류라는 서술은 생략오류의 정의가 아님","시간오류(timing): 업무를 정해진 시간보다 너무 빠르게 혹은 늦게 수행","순서오류(sequence): 업무 순서를 잘못 이해","실행오류(commission): 해야 할 업무를 부정확하게 수행","부가오류(extraneous): 불필요한 절차를 수행","스웨인 분류의 범위: 시간에러는 해당 · 위반에러는 해당하지 않음"]},{"t":"def","term":"리즌·라스뮤센 분류","text":"리즌의 불안전행동과 라스뮤센의 행동 분류","ex":["위반(violation): 고의성 있는 위험한 행동","실책·착오(mistake): 부적절한 의도(계획)에서 발생","실수(slip): 의도하지 않았고 어떤 기준에 맞지 않는 행동","건망증(lapse): 기억 실패 · 의도를 가지고 실행한 행동이 아님","불안전행동의 인식: 불안전행동 중에는 실제 행동으로 나타나지 않고 당사자만 인식하는 것도 있음","인간 행동 분류: 숙련 기반(skill), 규칙 기반(rule), 지식 기반(knowledge)","숙련기반행동: 충분히 습득해 자동적으로 하는 행동","규칙기반행동: 친숙한 상황에서 저장된 규칙을 적용하는 행동","지식기반행동: 낯설고 새로운 상황에서 정보를 그때마다 · 의식적·체계적으로 처리해 나타난 행동","수행기반행동: 라스뮤센 분류에 없는 용어","기출 2024-64: 정답표는 5(ㄱ, ㄷ, ㄹ)로 기록돼 있으나 위 정의와 맞지 않음 · 정답표 오류 가능성"]},{"t":"def","term":"인적 요인·정보처리·뇌파","text":"인적 요인, 정보처리 순서, 위험감수성, 뇌파","ex":["산업재해의 인적 요인: 불안전행동, 인간 오류, 사고 경향성, 직무 스트레스 · 작업 환경은 인적 요인이 아님","정보처리 순서: 감각(자극) -> 지각 -> 주의 -> 기억 -> 결정 -> 행동 실행 · 행동 실행 바로 앞 단계는 결정","위험감수성 하부 요인: danger sensitivity · 체험·관찰적 요인, 인지적 요인, 지각적 요인, 정서적 요인 · 전술적 요인은 아님","델타(δ)파: 무의식, 실신, 깊은 수면 상태","세타(θ)파: 피로, 졸림 상태","알파(α)파: 편안한 휴식 상태","베타(β)파: 깨어서 활동하는 각성·집중 상태","오메가(Ω)파: 과도한 집중과 긴장 상태(기출 표기)"]},{"t":"def","term":"주의 이론·각성·착시","text":"주의 이론, 각성 수준, 착시","ex":["브로드벤트 여과기 모델: 선택되지 않은 메시지는 차단","트레이스만 여과기 약화(감쇠) 모델: 무주의 정보도 약화된 채 일부 처리됨","여키스-도슨 법칙: 수행은 각성 수준과 역U자 관계 · 단순 과제는 높은 각성 수준에서, 복잡 과제는 낮은 각성 수준에서 최적 수행","경계(vigilance) 과제: 불규칙한 희귀 신호를 장시간 탐색하면 · 지속 주의가 떨어져 탐지 실수 증가(경계 감소)","높은 스트레스 환경: 각성을 과도하게 높여 주의 폭이 좁아지고 수행이 저하될 수 있음","메시지 분리: 표적 메시지와 방해 메시지를 공간적으로 분리하면 · 표적 메시지에 더 쉽게 주의를 기울일 수 있음","크기 착시: 뮬러-라이어, 폰조, 에빙하우스, 델뵈프 · 포겐도르프 착시는 방향 착시이므로 크기 착시가 아님","길이와 관련된 착시: 폰조 착시(뮬러-라이어도 길이 착시)","죌너 착시: 평행선이 기울어져 보이는 방향 착시로 분류되는 것이 일반적 · 기출 2024-67 정답표는 면적 착시에 5(죌너)로 기록돼 있어 일반 분류와 다름"]}],"#13":[{"t":"table","title":"산업위생의 정의와 외국 인물","head":["항목","내용"],"rows":[["산업위생","근로자와 일반 대중에게 질병과 건강장해를 일으킬 수 있는 작업환경 요인과 스트레스를 예측, 인지(확인), 평가, 관리하는 과학과 기술(AIHA)"],["산업위생의 목적","유해인자 예측 및 관리, 작업조건의 인간공학적 개선, 작업환경 개선 및 직업병 예방, 작업자의 건강보호 및 생산성 향상 · 네 가지 전부 해당"],["아그리콜라(Agricola)","독일 의사, 광물에 대하여(De Re Metallica) 저술, 먼지에 의한 규폐증 기록"],["라마찌니(Ramazzini)","이탈리아 의사, 직업인의 질병 저술 · 산업보건(직업의학)의 시조"],["포트(Pott)","굴뚝청소부와 음낭암의 관계 규명(1775)"],["해밀턴(Alice Hamilton)","미국 산업의학·산업위생의 선구자(납 등 연구)"],["퍼시벌(Percival)","영국 의사, 공장 근로조건 개선과 공장법 제정에 영향"],["히포크라테스","납중독을 기록한 것으로 알려진 고대 의사"],["플리니(Pliny the Elder)","아연·황 취급자의 호흡 보호를 위해 동물 방광 마스크를 쓰도록 기록"],["파라셀수스","독성학의 시조 · 모든 물질은 독이며 용량이 독을 결정한다는 용량-반응 개념"],["베이커(Baker)","사이다 공장에서 납에 의한 복통을 규명한 사람으로 알려짐 · 갈렌이 아님"]]},{"t":"table","title":"한국의 산업보건 역사와 노출-반응","head":["항목","내용"],"rows":[["1953년","산업보건 내용이 처음 포함된 법령은 근로기준법"],["대표 직업병 집단 발생 순서","원진레이온 이황화탄소 중독 -> 전자부품 업체 2-브로모프로판 생식독성(1995) -> 노말헥산 외국인 근로자 다발성 말초신경 장해 -> 휴대전화 부품 협력업체 메탄올 시신경 장해 -> 에어컨 부속 제조업체 트리클로로메탄 간독성"],["2022 기출 정답 순서","ㅁ -> ㄴ -> ㄹ -> ㄷ -> ㄱ"],["항상성(homeostasis)","노출에 적응해 정상 조절이 가능한 단계"],["정상기능 유지단계","방어기능을 동원해 기능장해를 막는 대상성(compensation) 조절 단계 · 대상성 조절 단계를 벗어나면 회복 불가능한 질병이 생김"],["활동능력 상실과 조절능력 상실","노출에 따른 활동능력 상실과 조절능력 상실 관계는 지수형 곡선"]]}],"#14":[{"t":"table","title":"노출기준의 정의·종류·유의사항","head":["항목","내용"],"rows":[["노출기준","노출기준 이하 수준에서는 거의 모든 근로자에게 건강상 나쁜 영향을 미치지 아니하는 기준 · TWA, STEL, C로 표시(노출기준 고시 제2조)"],["TWA","1일 8시간 작업 기준, 유해인자 측정치에 발생시간을 곱해 8시간으로 나눈 값 · TWA = (C1T1 + C2T2 + ... + CnTn) / 8"],["STEL","15분간의 시간가중평균노출값 · TWA 초과 STEL 이하인 경우 1회 노출 지속시간 15분 미만, 1일 4회 이하, 각 노출 간격 60분 이상 · STEL 괄호 문제 합: 15 + 15 + 60 = 90 (2022 기출)"],["최고노출기준(C)","근로자가 1일 작업시간 동안 잠시라도 노출되어서는 아니 되는 기준 · 노출기준 앞에 C를 붙여 표시"],["단독 존재 기준(제3조, 제4조)","각 유해인자 노출기준은 단독으로 존재하는 경우의 기준 · 2종 이상 혼재하면 상가작용으로 유해성이 증가할 수 있어 제6조의 식으로 산출한 기준 사용"],["작업 조건 고려","노출기준은 1일 8시간 작업 기준 · 근로시간, 작업강도, 온열조건, 이상기압 등을 고려해야 함"],["사용하면 안 되는 경우","노출기준은 직업병 진단에 쓰거나, 기준 이하라는 이유만으로 직업성 질병 이환을 부정하는 근거·반증자료로 쓰면 안 됨 · 대기오염의 평가 또는 관리상의 지표로 쓰면 안 됨"],["사용 용도","노출기준은 작업환경 개선기준과 작업환경측정 결과의 평가기준으로 사용 · 고시에 없는 인자는 ACGIH TLV를 준용"],["혼합물","서로 다른 인체 부위에 작용한다는 증거가 없으면 유해작용이 가중 · 계산값 C1/T1 + C2/T2 + ... 이 1을 초과하지 않아야 함 · 서로 다른 부위에 작용하는 경우 각각 작용하므로 어느 하나라도 노출기준을 넘으면 초과"],["발암성·생식독성 정보","발암성·생식세포 변이원성·생식독성 정보는 규제 목적이 아닌 정보 제공 목적 표시"],["고시 타당성 검토","2020년 1월 1일 기준 매 3년이 되는 시점마다 · 5년이 아님"]]},{"t":"table","title":"표시단위와 물질별 표시","head":["항목","내용"],"rows":[["표시단위","가스 및 증기: ppm · 분진·미스트·흄 등 에어로졸: mg/m3 · 석면·내화성세라믹섬유: 개/cm3"],["고온의 표시단위","WBGT(습구흑구온도지수), 단위 섭씨온도(℃)"],["WBGT(옥외 일사 있는 곳)","0.7 x 자연습구온도 + 0.2 x 흑구온도 + 0.1 x 건구온도"],["WBGT(옥내 또는 일사 없는 옥외)","0.7 x 자연습구온도 + 0.3 x 흑구온도"],["라돈·충격소음 기준","라돈 노출기준 600 Bq/m3, 최대음압수준 140 dB(A) 초과 충격소음 노출 금지"],["소음작업","1일 8시간 기준 85 데시벨 이상 소음 발생 작업"],["강렬한 소음작업","90dB 이상 1일 8시간 이상, 95dB 4시간, 100dB 2시간, 105dB 1시간, 110dB 30분, 115dB 15분 이상"],["충격소음작업","120dB 초과 1일 1만회, 130dB 초과 1천회, 140dB 초과 100회 이상"],["보정노출기준(1일 8시간 초과 작업)","Brief-Scala 식 보정노출기준 = 8시간 노출기준 x (8/H) x [(24-H)/16] · H는 1일 노출시간"],["Skin 표시물질","피부자극성이 아니라 점막·눈·경피로 흡수되어 전신 영향을 일으킬 수 있는 물질"],["발암성 정보 표기","화학물질의 분류·표시 및 MSDS 기준에 따라 1A, 1B, 2"],["납 및 그 무기화합물","TWA 0.05 mg/m3, 발암성 1B, 생식독성 1A"],["내화성세라믹섬유","TWA 0.2 개/cm3, 호흡성, 발암성 1B"],["니켈","가용성화합물 TWA 0.1 mg/m3 발암성 1A · 불용성 무기화합물 0.2 mg/m3 발암성 1A · 금속 1 mg/m3 발암성 2 · 니켈 카르보닐 0.001 ppm"],["디메틸포름아미드","TWA 10 ppm, 생식독성 1B, Skin"],["크롬산 아연","발암성 1A"],["2021 기출 오답 선지","인듐 및 그 화합물에 흡입성 표기를 연결한 선지는 오답(바른 표기는 미확인) · 일산화탄소-호흡성도 오답 · 불화수소는 생식세포 변이원성 2 아님 · 트리클로로에틸렌은 생식독성 1A 아님"],["2025 기출 TWA","정답 외 TWA: 납 0.05, 니켈(불용성) 0.2, 망간 및 무기화합물 1, 주석(유기화합물) 0.1 mg/m3 는 옳은 값 · 인듐 및 그 화합물 0.5는 옳지 않음 · 인듐 및 그 화합물의 TWA는 0.01 mg/m3로 알려짐"],["발암성 1A","비소 및 무기화합물, 니켈(가용성화합물), 베릴륨 및 화합물, 크롬(6가)화합물(수용성) · 코발트 및 무기화합물은 1A가 아님"],["1,2-에폭시프로판","발암성 1B(시험동물 발암성 증거 충분 또는 시험동물과 사람 모두 제한적 증거)이며 생식세포 변이원성 1B에 해당"]]},{"t":"table","title":"작업환경측정 대상과 방법","head":["항목","내용"],"rows":[["측정 주기","신규 가동·변경 시 30일 이내 측정, 이후 반기에 1회 이상"],["3개월에 1회 이상으로 단축","별표 21 제1호 화학적 인자(고시 물질)의 측정치가 노출기준 초과, 또는 고시 물질 외 화학적 인자가 노출기준의 2배 이상 초과"],["연 1회 이상 가능","최근 1년간 공정 변화가 없고, 소음이 최근 2회 연속 85dB 미만이거나 소음 외 모든 인자가 최근 2회 연속 노출기준 미만(고시 물질 취급 공정 제외)"],["측정 방법","예비조사, 정상 작업 시 실시, 모든 측정은 개인 시료채취가 원칙(곤란하면 지역 시료채취, 사유를 결과표에 명시)"],["물리적 인자 2종","8시간 TWA 80dB 이상의 소음, 고열 · 진동·전리방사선·분진·미스트는 물리적 인자 대상이 아님"],["분진 대상(7종)","광물성 분진, 곡물 분진, 면 분진, 목재 분진, 석면 분진, 용접 흄, 유리섬유"],["화학적 인자","유기화합물 114종, 금속류 24종, 산·알칼리류 17종, 가스상 물질류 15종, 허가대상 유해물질 12종, 금속가공유 1종"],["별표 21 유기화합물 예","디메틸포름아미드, 벤젠, 포름알데히드, 1-브로모프로판, 2-브로모프로판, 아크릴로니트릴, 1,3-부타디엔, 트리클로로에틸렌, 니트로글리세린, 트리에틸아민, 이황화탄소, 사염화탄소, 아크릴아미드 · 포름아미드(75-12-7)는 별표 21 유기화합물 목록에 없음"],["별표 21 대상","디에틸아민, 디에틸에테르, 무수프탈산, 브롬화메틸, 피리딘은 모두 별표 21 대상 · 이 중 특수건강진단 대상이 아닌 것은 디에틸아민(2023 기출) · 납, 니켈, 망간, 인듐, 주석, 코발트, 크롬, 카드뮴 등이 금속류 목록에 포함"],["정확도와 정밀도","정확도: 분석치가 참값에 얼마나 접근했는가 · 정밀도: 반복 측정·분석 시 분석치 변동 크기가 얼마나 작은가"],["채취방법","고체채취방법: 시료공기를 고체 입자층으로 흡입·흡착 · 직접채취방법: 흡수·흡착 없이 채취용기에 직접 채취 · 액체채취방법: 액체에 통과·접촉시켜 용해·반응·흡수 · 냉각응축채취, 여과채취도 있음"],["분진 구분","호흡성분진: 폐포에 축적될 수 있는 크기의 분진 · 흡입성분진: 호흡기 어느 부위에 침착하더라도 독성을 일으키는 분진"],["시료채취 위치","개인 시료채취: 근로자 호흡위치(호흡기 중심 반경 30cm 반구)에서 채취 · 지역 시료채취: 작업행동 범위에서 호흡기 높이에 고정"],["TWA 설정물질 측정","1일 작업시간 동안 6시간 이상 연속 측정하거나 작업시간을 등간격으로 나눠 6시간 이상 연속분리 측정 · 예외: 발생시간이 6시간 이하, 불규칙 작업으로 6시간 이하, 발생원 발생이 간헐적이면 발생시간 동안 측정 가능"],["STEL·C 설정물질 측정","STEL 설정물질은 단시간 노출평가가 필요하다고 판단하면 TWA 측정에 추가하여 단시간 측정(1회 15분) · TWA 측정을 대신하는 것이 아님 · 최고노출기준(C) 설정물질은 최고노출 수준을 평가할 수 있는 최소한의 시간 동안 측정 · TWA도 설정되어 있으면 TWA 측정을 병행"],["시료채취 근로자수","단위작업 장소에서 최고 노출근로자 2명 이상에 대해 동시에 개인 시료채취(근로자 1명이면 제외) · 동일 작업근로자수가 10명을 초과하면 매 5명당 1명 이상 추가 · 100명을 초과하면 최대 시료채취 근로자수를 20명으로 조정 가능"],["지역 시료채취","단위작업장소 내 2개 이상 지점에서 동시에 측정 · 넓이 50m2 이상이면 매 30m2마다 1개 지점 이상 추가"],["검지관방식","예비조사 목적 등에 한정 · 1일 작업시간 동안 1시간 간격 6회 이상, 측정시간마다 2회 이상 반복 측정해 평균 · 노출기준 초과 시 즉시 재측정, 자격자 검지관 측정 사업장은 2년에 1회 이상 사업장 위탁측정기관 측정"],["소음 측정","A특성, 누적소음 노출량측정기 Criteria 90dB, Exchange Rate 5dB, Threshold 80dB · 단위작업 장소 6시간 이상 연속 또는 1시간 간격 6회 이상"],["고열 측정","WBGT 기기, 바닥 50cm 이상 150cm 이하, 가장 높은 고열에 노출되는 1시간을 10분 간격으로 연속 측정"],["측정 시기 간격","반기 1회 주기이면 전회 측정 완료일부터 3개월 이상, 3개월 1회이면 45일 이상, 연 1회이면 6개월 이상"],["결과 보고와 설명회","위탁측정기관은 측정 완료일부터 30일 이내 결과표 작성 · 노출기준 초과 시 개선계획서 첨부 제출 · 산업안전보건위원회·근로자대표 요구 시 측정기관으로부터 결과를 통보받은 날부터 10일 이내 측정결과 설명회 실시"],["분석 방법","가스상 물질 분석: 원자흡광분석, 가스크로마토그래프분석 등으로 정량 · 입자상: 여과채취 후 중량분석 또는 적합 방법 · 석면 농도는 여과채취 후 계수방법으로 분석"],["근로자대표","사업주는 작업환경측정을 하기 위해 근로자대표가 요구하면 참석시켜야 하고, 측정 결과를 근로자에게 알려야 함"]]},{"t":"table","title":"시료채취 매체·조명·열 교환·생물학적 노출지표","head":["항목","내용"],"rows":[["트리클로로에틸렌","활성탄관으로 채취"],["2021 기출 오답 연결","2-브로모프로판-실리카겔관, 디메틸포름아미드-활성탄관, 시클로헥산-실리카겔관, 니켈-활성탄관"],["암모니아 분석","IC(이온크로마토그래피)와 전도도검출기"],["수동식 시료채취기(passive sampler)","확산 또는 투과 원리로 채취하며 간섭 원리가 아님 · 장점은 간편성·편리성 · 작업장에 최소한의 기류 필요 · 채취시간, 기류, 온도, 습도 영향 · 낮은 농도 측정은 능동식보다 시간이 더 소요"],["광도","광원의 밝기 정도(단위 칸델라)"],["조도","물체 표면에 도달하는 빛의 양(단위 럭스)"],["휘도","단위 면적당 표면에서 반사 혹은 방출되는 빛의 양 · 반사율은 조도와 광도의 비율이 아님(휘도와 조도의 관계로 정의됨)"],["열 교환 4경로","대류(공기 기류), 복사(전자파), 증발(땀이 수증기로 변하며 열 흡수), 전도(고체·유체와 직접 접촉) · 반사는 열 교환 경로에 포함되지 않음"],["노말-헥산","소변 중 2,5-헥산디온 5 mg/L"],["메틸클로로포름","소변 중 삼염화초산 10 mg/L"],["크실렌","소변 중 메틸마뇨산 1.5 g/g crea"],["인듐","혈청 중 인듐 1.2 ug/L"],["톨루엔","소변 중 o-크레졸 1 mg/g crea 는 기출에서 옳지 않은 값으로 처리"]]}],"#15":[{"t":"table","title":"건강진단의 종류(산업안전보건법)","head":["항목","내용"],"rows":[["일반건강진단","사업주가 상시 사용하는 근로자의 건강관리를 위해 실시 · 특수건강진단기관 또는 건강진단기관에서 실시"],["특수건강진단","특수건강진단대상업무 종사 근로자, 그리고 직업병 소견 판정 후 작업 전환·장소 변경한 근로자로서 해당 유해인자 건강진단이 필요하다는 의사 소견이 있는 근로자"],["배치전건강진단","특수건강진단대상업무에 종사할 근로자의 배치 예정 업무 적합성 평가"],["수시건강진단","특수건강진단대상업무 유해인자로 인한 것으로 의심되는 건강장해 증상·의학적 소견이 있는 근로자 중 보건관리자 등이 건강진단 실시를 건의하는 등 부령 기준에 해당하는 근로자"],["임시건강진단","고용노동부장관이 같은 유해인자에 노출되는 근로자들에게 유사한 질병 증상이 발생한 경우 등에 사업주에게 건강진단 실시·작업전환 등을 명령"],["종합건강진단·건강관리카드","종합건강진단은 건강진단의 종류가 아님 · 건강관리카드 소지자 건강진단은 종류에 해당"],["사업주 의무","사업주는 근로자대표가 요구하면 건강진단에 참석시켜야 함 · 개별 근로자의 결과는 본인 동의 없이 공개 금지 · 건강 보호·유지 외 목적으로 사용 금지"],["결과에 따른 조치","작업장소 변경, 작업 전환, 근로시간 단축, 야간근로(오후 10시~오전 6시) 제한, 작업환경측정, 시설·설비 설치·개선 등 적절한 조치"]]},{"t":"table","title":"일반·특수건강진단의 주기와 판정","head":["항목","내용"],"rows":[["일반건강진단 주기","사무직은 2년에 1회 이상, 그 밖의 근로자는 1년에 1회 이상"],["제1차 검사항목","과거병력·작업경력·자각타각증상, 혈압·혈당·요당·요단백·빈혈, 체중·시력·청력, 흉부방사선 촬영, AST·ALT·γ-GTP·총콜레스테롤"],["제2차 건강진단","질병 확진이 곤란하면 제2차 건강진단을 받아야 함"],["일반건강진단 갈음","국민건강보험법 건강검진 등 일정 건강진단을 실시하면 일반건강진단을 실시한 것으로 인정"],["특수건강진단 주기 단축","유해인자별 시기·주기에 따라 실시 · 작업환경측정 결과 노출기준 이상인 공정 노출 근로자 전원은 다음 회에 한정해 주기를 2분의 1로 단축 · 특수·수시·임시건강진단에서 직업병 유소견자가 발견된 공정 노출 근로자 전원도 주기 2분의 1 단축(의사가 단축 불필요 소견이면 제외) · 의사가 단축해야 한다는 소견을 낸 근로자도 단축"],["판정 구분","A 정상, C1 직업병 요관찰자, C2 일반질병 요관찰자, D1 직업병 유소견자, D2 일반질병 유소견자, R 제2차 건강진단 대상 · 직업성 질병으로 진전될 가능성이 있어 추적 관찰이 필요한 판정은 C1(직업병 요관찰자)"],["건강진단 결과표(별지 제85호 서식)","작성 사항: 유해인자별 건강진단 받은 근로자 현황, 질병코드별 질병유소견자 현황, 질병별 조치 현황, 작성일·송부일·검진기관명 · 작업공정별 유해요인 분포 실태는 아님"]]},{"t":"table","title":"유해인자와 건강장해","head":["항목","내용"],"rows":[["감압환경","관절 통증(잠함병)"],["일산화탄소","혈색소와 결합해 조직 저산소증 · 재생불량성 빈혈은 일산화탄소의 건강장해가 아님"],["망간","파킨슨병 유사 증상 · 접촉성 피부염과 비중격 점막 괴사는 망간이 아니라 크롬의 영향 · 망간에 연결하면 오답"],["납","조혈기능 장해, 헴 합성 과정 장해로 혈색소량 감소·적혈구 생존기간 단축, 적혈구와 친화성이 높아 뼈조직 결합 · 임상증상: 급성 복부 산통의 위장계통 장해, 손처짐 동반 팔·손 마비의 신경근육계통 장해, 급성 뇌병증 등 중추신경계통 장해"],["사염화탄소","간독성"],["니켈","폐암, 비강암, 눈 자극증상"],["오산화바나듐","천식, 폐부종, 피부습진"],["베릴륨","기침, 호흡곤란, 폐의 육아종 형성"],["카드뮴","만성 폐쇄성 호흡기 질환, 폐기종 · 특수건강진단 제1차 검사항목: 혈중 카드뮴(기출 정답) · 소변 중 카드뮴, 베타2 마이크로글로불린, 객담세포검사, 단백뇨정량은 정답이 아님"],["세균성 질환","파상풍, 탄저병, 레지오넬라증, 결핵 · 광견병은 바이러스성이라 세균성이 아님"],["2024년 산업재해현황분석","직업병자 수가 가장 많은 질병은 난청"]]}],"#16":[{"t":"table","title":"후드 제어풍속(별표 13·별표 17)","head":["항목","내용"],"rows":[["별표 13 기본","국소배기장치를 설치할 때는 별표 13의 제어풍속을 낼 수 있는 성능을 갖춰야 함 · 가스 상태는 가스·증기, 입자 상태는 흄·분진·미스트"],["가스 상태(m/sec)","포위식 포위형 0.4, 외부식 측방흡인형 0.5, 외부식 하방흡인형 0.5, 외부식 상방흡인형 1.0"],["입자 상태(m/sec)","포위식 포위형 0.7, 외부식 측방흡인형 1.0, 외부식 하방흡인형 1.0, 외부식 상방흡인형 1.2 · 2025 기출 정답: 입자 - 외부식 상방흡인형 - 1.2 m/sec"],["제어풍속 측정","제어풍속은 모든 후드를 개방한 상태의 풍속 · 포위식은 후드 개구면에서, 외부식은 빨아들이려는 범위 내에서 개구면으로부터 가장 먼 거리의 작업위치에서 측정"],["일반 분진작업(별표 17, m/sec)","포위식 0.7, 외부식 측방흡인형 1.0, 하방흡인형 1.0, 상방흡인형 1.2"],["주형을 부수고 모래를 터는 장소","포위식 0.7, 외부식 측방흡인형 1.3, 하방흡인형 1.3 · 포위식이 외부식 측방흡인형보다 낮음"],["체로 거르는 장소와 주물모래 재생 장소","암석 등 탄소원료·알루미늄박을 체로 거르는 장소와 주물모래 재생 장소: 포위식 0.7"],["회전체를 가지는 기계(m/sec)","기계 전체를 포위하는 방법 0.5, 회전체만 포위하는 방법 5.0, 분진 흩날림 방향을 개구면으로 덮는 방법 5.0 · 회전체 후드 제어풍속은 회전체를 정지한 상태에서 개구면의 최소풍속"]]},{"t":"table","title":"후드 설계 원칙","head":["항목","내용"],"rows":[["설치 위치","공기보다 무거운 증기가 발생하더라도 발생원보다 낮은 위치에 후드를 설치해서는 안 됨 · 공정에 지장이 없으면 후드 개구부에 플랜지를 부착하고 오염원 가까이에 설치"],["필요환기량","필요환기량은 최소화 · 최대화는 오답"],["정압","주관과 분지관 합류점의 정압 차이는 작게(균형 유지) · 크게 하면 오답"],["개구면 속도 균일화 방법","경사접합부(taper)와 플레넘(plenum), 차폐막(baffle), 슬롯(slot), 분리날개(splitter vanes) · 피토관은 풍속·정압 측정 기구이므로 개구면 속도 균일화 방법이 아님"],["후드 형태","포위식(커버형, 부스형), 외부식(측방, 상방, 하방 흡인형), 리시버식(캐노피, 그라인더 등)"]]},{"t":"table","title":"보호구와 공기정화장치","head":["항목","내용"],"rows":[["송기마스크를 착용시켜야 하는 업무","유기화합물을 넣었던 탱크 내부(증기 발산 우려가 없는 탱크 제외) 세척·페인트칠, 유기화합물 취급 특별장소에서의 취급업무"],["송기마스크나 방독마스크를 착용시켜야 하는 업무","밀폐설비·국소배기장치가 설치되지 않은 장소의 유기화합물 취급(제423조제1·2항, 제424조제1항, 제425조, 제426조, 제428조제1항에 따른 경우) · 유기화합물 취급 장소에 설치된 환기장치 내 기류가 확산될 우려가 있는 물체를 다루는 업무 · 유기화합물 증기 발산원을 밀폐하는 설비를 개방하는 업무(단 청소 등으로 유기화합물이 제거된 설비는 제외)"],["착용 대상이 아닌 업무","청소 등으로 유기화합물이 제거된 설비를 개방하는 업무는 착용 대상이 아님(2021 기출 정답)"],["지급 기준","송기마스크는 신선한 공기를 공급할 수 있는 성능을 가진 장치가 부착된 것을 지급 · 금속류, 산·알칼리류, 가스상태 물질류 취급 작업장에서는 적절한 호흡용 보호구 지급, 공동 사용으로 감염 우려가 있으면 개인 전용 지급 · 근로자는 지급된 보호구를 사업주 지시에 따라 착용"],["집진(먼지제거) 원리","세정, 여과(여포), 원심력(사이클론), 전기 전하(전기집진), 중력 침강, 관성 충돌 · 흡착은 집진 원리가 아니라 가스·증기 처리 방법(활성탄 등)"],["가스상 오염물질 처리","흡수(세정), 흡착, 연소(산화)"]]}]};
